import { sampleAudit } from "@/content/sample-audit";
import { site } from "@/content/site";

/** Small, fast model. Keep the preview cheap. */
export const PREVIEW_MODEL = "gpt-4o-mini";

export const PREVIEW_LABEL =
  "Example preview generated by AI. A person reviews every real audit, and you'll hear from Chris within one business day.";

export const PREVIEW_FALLBACK =
  "We could not draft a preview just now. You can still send the form, and a person will review it.";

/** Contact form reads these query names to prefill the try-it answers. */
export function fullAuditHref(industry: string, weeklyTime: string): string {
  const params = new URLSearchParams();
  const industryText = industry.trim().slice(0, 120);
  const weeklyText = weeklyTime.trim().slice(0, 500);
  if (industryText) params.set("industry", industryText);
  if (weeklyText) params.set("weekly_time", weeklyText);
  const query = params.toString();
  return query ? `/contact?${query}` : "/contact";
}

const HOUR_MS = 60 * 60 * 1000;
const PREVIEW_LIMIT = 5;
const FIELD_MAX = 280;

const hits = new Map<string, number[]>();

export type PreviewWorkflow = {
  name: string;
  handles: string;
  person: string;
  tools: string;
};

export type PreviewInput = {
  industry: string;
  drains: string;
  weeklyTime: string;
};

export function auditPreviewConfigured(env: NodeJS.ProcessEnv = process.env): boolean {
  return Boolean(env.OPENAI_API_KEY?.trim());
}

let lastPreviewErrorCode: string | null = null;

/** Presence and shape of the key, plus the last failure code. Never the key itself. */
export function previewHealth(env: NodeJS.ProcessEnv = process.env): {
  keyPresent: boolean;
  keyPrefixOk: boolean;
  lastErrorCode: string | null;
} {
  const key = (env.OPENAI_API_KEY ?? "").trim();
  return {
    keyPresent: key.length > 0,
    keyPrefixOk: key.startsWith("sk-") && key.length >= 20 && !/\s/.test(key),
    lastErrorCode: lastPreviewErrorCode,
  };
}

function safeErrorToken(value: string): string {
  const trimmed = value.trim().slice(0, 80);
  if (!/^[A-Za-z0-9_.:-]{1,80}$/.test(trimmed)) return "";
  if (/sk-[A-Za-z0-9]|bearer/i.test(trimmed)) return "";
  return trimmed;
}

function logPreviewFailure(detail: {
  status?: number;
  code?: string;
  type?: string;
  category: string;
}): void {
  const code = detail.code ? safeErrorToken(detail.code) : "";
  const type = detail.type ? safeErrorToken(detail.type) : "";
  const category = safeErrorToken(detail.category) || "unknown";
  const status = Number.isInteger(detail.status) ? detail.status : undefined;
  console.error(
    "audit preview failed",
    JSON.stringify({
      ...(status === undefined ? {} : { status }),
      ...(code ? { code } : {}),
      ...(type ? { type } : {}),
      category,
    }),
  );
  lastPreviewErrorCode = code || type || category;
}

async function readOpenAiError(response: Response): Promise<{ code: string; type: string }> {
  try {
    const payload = (await response.json()) as { error?: { code?: unknown; type?: unknown } };
    return {
      code: typeof payload.error?.code === "string" ? payload.error.code : "",
      type: typeof payload.error?.type === "string" ? payload.error.type : "",
    };
  } catch {
    return { code: "", type: "" };
  }
}

export function resetPreviewRateLimit(): void {
  hits.clear();
}

/** Five previews an hour for one address, in this server process. */
export function allowPreview(address: string, now = Date.now()): boolean {
  const key = address.trim().slice(0, 200) || "unknown";
  const recent = (hits.get(key) ?? []).filter((time) => now - time < HOUR_MS);
  if (recent.length >= PREVIEW_LIMIT) {
    hits.set(key, recent);
    return false;
  }
  recent.push(now);
  hits.set(key, recent);
  return true;
}

export function canRequestPreview(input: PreviewInput): boolean {
  const sink = input.drains.trim().length >= 10 || input.weeklyTime.trim().length >= 10;
  return input.industry.trim().length > 0 && sink;
}

function blockedNames(): string[] {
  return [
    ...site.implementations.map((item) => item.name),
    sampleAudit.business,
    "Doan",
    "CapoVino",
    "BCLE",
    "FiberOptics",
    "Linden",
    "Ivers",
    "Trolley Barn",
  ];
}

const MONEY = /\$|\b\d[\d,]*(?:\.\d+)?\s*(?:usd|dollars?)\b|\b(?:usd|dollars?)\s*\d/i;
const PERCENT = /%|\b\d[\d,]*(?:\.\d+)?\s*percent(?:s|age)?\b|\bpercent(?:s|age)?\s*\d/i;
const ROI = /\broi\b/i;
const GUARANTEE = /guarant/i;
const PRICE = /\bpric(?:e|es|ed|ing)\b/i;
const HOURS = /\b\d[\d,]*(?:\.\d+)?\s*(?:hours?|hrs?)\b|\bhours?\s+saved\b/i;

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** Whole names only, so a short token such as Ivers does not match drivers. */
function mentionsBlockedName(text: string): boolean {
  return blockedNames().some((name) => {
    const pattern = new RegExp(`(?:^|[^A-Za-z0-9])${escapeRegExp(name)}(?:$|[^A-Za-z0-9])`, "i");
    return pattern.test(text);
  });
}

/** Reject money, savings figures, guarantees, prices, and client names. */
export function previewTextAllowed(text: string): boolean {
  if (
    MONEY.test(text) ||
    PERCENT.test(text) ||
    ROI.test(text) ||
    GUARANTEE.test(text) ||
    PRICE.test(text) ||
    HOURS.test(text)
  ) {
    return false;
  }
  return !mentionsBlockedName(text);
}

export function sanitizeStoredPreview(value: unknown): string {
  if (typeof value !== "string") return "";
  const text = value.trim();
  if (!text || text.length > 4000) return "";
  if (!previewTextAllowed(text)) return "";
  return text;
}

function asField(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const text = value.trim().replace(/\s+/g, " ");
  if (!text || text.length > FIELD_MAX) return null;
  if (!previewTextAllowed(text)) return null;
  return text;
}

export function workflowsFromModel(content: string): PreviewWorkflow[] | null {
  const trimmed = content.trim().replace(/^```(?:json)?\s*/i, "").replace(/```$/, "").trim();
  let parsed: unknown;
  try {
    parsed = JSON.parse(trimmed);
  } catch {
    return null;
  }
  if (!parsed || typeof parsed !== "object" || !("workflows" in parsed)) return null;
  const workflows = (parsed as { workflows?: unknown }).workflows;
  if (!Array.isArray(workflows)) return null;
  const clean: PreviewWorkflow[] = [];
  for (const item of workflows) {
    if (!item || typeof item !== "object") continue;
    const record = item as Record<string, unknown>;
    const name = asField(record.name);
    const handles = asField(record.handles);
    const person = asField(record.person);
    const tools = asField(record.tools);
    if (!name || !handles || !person || !tools) continue;
    if (!previewTextAllowed(`${name} ${handles} ${person} ${tools}`)) continue;
    clean.push({ name, handles, person, tools });
    if (clean.length === 3) break;
  }
  if (clean.length < 2) return null;
  return clean;
}

export function previewPlainText(workflows: readonly PreviewWorkflow[]): string {
  return workflows
    .map((workflow) =>
      [
        workflow.name,
        `What the AI would handle: ${workflow.handles}`,
        `Where a person reviews: ${workflow.person}`,
        `Likely tools: ${workflow.tools}`,
      ].join("\n"),
    )
    .join("\n\n");
}

export function previewSystemPrompt(): string {
  const names = site.implementations.map((item) => item.name).join(", ");
  return [
    "You draft a short audit preview for Adtell.ai.",
    'Return JSON only: {"workflows":[{"name":"","handles":"","person":"","tools":""}]}.',
    "Return 2 or 3 workflows.",
    "Each workflow names a specific task from the industry and the work described.",
    "handles: what the automation would prepare.",
    "person: where a person reviews or approves before anything is sent.",
    "tools: everyday tools such as email, a spreadsheet, or a calendar.",
    "Do not include dollar amounts, prices, percentages, hours saved, ROI, or guarantees.",
    "Do not invent results, quotes, or statistics.",
    `Do not name these businesses: ${names}, ${sampleAudit.business}.`,
    "A person still approves what goes out.",
  ].join(" ");
}

export function previewUserPrompt(input: PreviewInput): string {
  const lines = [`Industry: ${input.industry.trim()}`];
  if (input.drains.trim()) lines.push(`The work that costs the most: ${input.drains.trim()}`);
  if (input.weeklyTime.trim()) {
    lines.push(`What eats the most time each week: ${input.weeklyTime.trim()}`);
  }
  return lines.join("\n");
}

function clip(value: unknown, max: number): string {
  const text = typeof value === "string" ? value.trim() : "";
  return text.length > max ? text.slice(0, max) : text;
}

export function readPreviewInput(
  body: Record<string, unknown>,
): { ok: true; value: PreviewInput } | { ok: false; message: string } {
  const industryRaw = typeof body.industry === "string" ? body.industry.trim() : "";
  const weeklyRaw = typeof body.weekly_time === "string" ? body.weekly_time.trim() : "";
  if (industryRaw.length > 120) return { ok: false, message: "Use 120 characters or fewer for the industry." };
  if (weeklyRaw.length > 500) return { ok: false, message: "Use 500 characters or fewer." };
  const value = {
    industry: clip(body.industry, 120),
    drains: clip(body.drains, 500),
    weeklyTime: clip(body.weekly_time, 500),
  };
  if (!canRequestPreview(value)) {
    return {
      ok: false,
      message: "Add the industry and the work that takes the time, then try the preview again.",
    };
  }
  return { ok: true, value };
}

export async function draftAuditPreview(
  input: PreviewInput,
  options: { apiKey: string; fetchImpl?: typeof fetch; timeoutMs?: number },
): Promise<{ ok: true; workflows: PreviewWorkflow[] } | { ok: false; message: string }> {
  const fetchImpl = options.fetchImpl ?? fetch;
  const timeoutMs = options.timeoutMs ?? 15_000;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetchImpl("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      signal: controller.signal,
      headers: {
        Authorization: `Bearer ${options.apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: PREVIEW_MODEL,
        temperature: 0.2,
        // Current chat-completions rejects max_tokens (unsupported_parameter) in a few hundred ms.
        max_completion_tokens: 450,
        response_format: { type: "json_object" },
        messages: [
          { role: "system", content: previewSystemPrompt() },
          { role: "user", content: previewUserPrompt(input) },
        ],
      }),
    });
    if (!response.ok) {
      const failure = await readOpenAiError(response);
      logPreviewFailure({
        status: response.status,
        code: failure.code,
        type: failure.type,
        category: "openai",
      });
      return { ok: false, message: PREVIEW_FALLBACK };
    }
    const payload = (await response.json()) as {
      choices?: { message?: { content?: string } }[];
    };
    const content = payload.choices?.[0]?.message?.content ?? "";
    const workflows = workflowsFromModel(content);
    if (!workflows) {
      logPreviewFailure({ category: "filtered", code: "filtered" });
      return { ok: false, message: PREVIEW_FALLBACK };
    }
    return { ok: true, workflows };
  } catch (err) {
    const name = err && typeof err === "object" && "name" in err ? String(err.name) : "";
    if (name === "AbortError") logPreviewFailure({ category: "timeout", code: "timeout" });
    else logPreviewFailure({ category: "network", code: "network" });
    return { ok: false, message: PREVIEW_FALLBACK };
  } finally {
    clearTimeout(timer);
  }
}

function requestAddress(request: Request): string {
  const forwarded = request.headers.get("x-forwarded-for");
  const first = forwarded?.split(",")[0]?.trim();
  if (first) return first.slice(0, 200);
  return "unknown";
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json", "Cache-Control": "no-store" },
  });
}

const MAX_BODY = 20_000;

export async function handleAuditPreview(
  request: Request,
  options?: { fetchImpl?: typeof fetch; env?: NodeJS.ProcessEnv; timeoutMs?: number },
): Promise<Response> {
  const env = options?.env ?? process.env;
  const contentType = request.headers.get("content-type") ?? "";
  if (!contentType.includes("application/json")) {
    return json({ ok: false, message: PREVIEW_FALLBACK }, 415);
  }
  let text = "";
  try {
    text = await request.text();
  } catch {
    return json({ ok: false, message: PREVIEW_FALLBACK }, 400);
  }
  if (text.length > MAX_BODY) return json({ ok: false, message: PREVIEW_FALLBACK }, 413);

  let payload: unknown;
  try {
    payload = JSON.parse(text);
  } catch {
    return json({ ok: false, message: PREVIEW_FALLBACK }, 400);
  }
  if (!payload || typeof payload !== "object") {
    return json({ ok: false, message: PREVIEW_FALLBACK }, 400);
  }
  const body = payload as Record<string, unknown>;
  const honeypot = typeof body.company_website === "string" ? body.company_website.trim() : "";
  if (honeypot) return json({ ok: false, message: PREVIEW_FALLBACK });

  const input = readPreviewInput(body);
  if (!input.ok) return json({ ok: false, message: input.message }, 400);

  const apiKey = env.OPENAI_API_KEY?.trim() ?? "";
  if (!apiKey) return json({ ok: false, message: PREVIEW_FALLBACK });

  if (!allowPreview(requestAddress(request))) {
    return json({ ok: false, message: PREVIEW_FALLBACK }, 429);
  }

  const drafted = await draftAuditPreview(input.value, {
    apiKey,
    fetchImpl: options?.fetchImpl,
    timeoutMs: options?.timeoutMs,
  });
  if (!drafted.ok) return json({ ok: false, message: drafted.message });
  return json({ ok: true, workflows: drafted.workflows });
}
